// Icon set for the redesigned home page.
//
// These are Lucide glyphs as exported by the design tool: the strokes were
// already flattened to filled paths, which is why each one is a single `d` on a
// 14x14 viewBox rather than the stroked paths of the upstream Lucide package.
// They paint with `currentColor`, so colour comes from CSS like any text.

type FillIconName =
  | "arrow-right"
  | "arrow-up-right"
  | "bell"
  | "bell-plus"
  | "bookmark-check"
  | "bookmark-plus"
  | "calendar-check"
  | "calendar-days"
  | "clapperboard"
  | "dices"
  | "flame"
  | "instagram"
  | "moon"
  | "play"
  | "radio"
  | "refresh-cw"
  | "search"
  | "send"
  | "sparkles"
  | "star"
  | "swords"
  | "users"
  | "wand-sparkles"
  | "youtube"

export type IconName = FillIconName | StrokeIconName;

const VIEW_BOX = "0 0 14 14";

// The glyphs iteration 2 added were not part of the design tool's export, so
// they are kept as upstream Lucide outlines on their native 24x24 grid and
// painted with a stroke instead. Circles are written out as arc pairs because
// each icon has to collapse into a single `d`.
export type StrokeIconName =
  | "calendar-clock"
  | "chart-no-axes-column"
  | "circle-play"
  | "eye"
  | "eye-off"
  | "heart"
  | "history"
  | "info"
  | "thumbs-down"
  | "thumbs-up"
  | "x";

