type Props = {
  name: IconName;
  /** Rendered size in px; the glyph scales from its 14px design grid. */
  size?: number;
  className?: string;
};

/**
 * A decorative glyph. It is always `aria-hidden`: every icon in the design sits
 * next to a visible label, or inside a button that carries its own aria-label,
 * so announcing the glyph too would only duplicate that.
 */
export function Icon({ name, size = 16, className }: Props) {
  if (isStroke(name)) {
    return (
      <svg
        viewBox={STROKE_VIEW_BOX}
        width={size}
        height={size}
        className={className}
        fill="none"
        stroke="currentColor"
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        focusable="false"
      >
        <path d={STROKE_PATHS[name]} />
      </svg>
    );
  }

  return (
    <svg
      viewBox={VIEW_BOX}
      width={size}
      height={size}
      className={className}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
    >
      <path d={PATHS[name]} />
    </svg>
  );
}
